import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { OrderService } from '../services/order.service';
import { saveAs } from 'file-saver';

@Component({
  selector: 'app-order-export',
  templateUrl: './order-export.component.html'
})
export class OrderExportComponent implements OnInit {
  accountId!: number;
  loading = false;
  error: string | null = null;

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private orderService: OrderService
  ) {}

  ngOnInit(): void {
    this.accountId = +this.route.snapshot.paramMap.get('id')!;
  }

  exportOrders(): void {
    this.loading = true;
    this.error = null;

    this.orderService.exportOrders(this.accountId).subscribe({
      next: (blob) => {
        saveAs(blob, `orders_${this.accountId}.csv`);
        this.loading = false;
      },
      error: (err) => {
        this.error = 'Failed to export orders';
        this.loading = false;
        console.error(err);
      }
    });
  }
}

